contentRule.content:
[class="videoplay_wrap"]@all
<js>
const startIndex = result.indexOf('url');
const endIndex = result.indexOf('"',startIndex+12);
const url = result.slice(startIndex+6, endIndex).replaceAll("\\","");
java.log(url)
java.startBrowser(url,chapter.title)
java.toast('正在加载视频\n视频加载较慢，请耐心等待')
' 【刷新正文】或【点击章节链接】跳转播放\n不要相信且不要点击视频里的任何广告，误触后请立即返回\n🔗直链:\n'+url
</js>

